mapper.delete:
DELETE FROM meal_item
WHERE id = #{id}
AND source_type = 'PERSONAL'
AND owner_user_id = #{userId}

mapper.select:
SELECT 
FROM meal_item
WHERE id = #{id}
AND source_type = 'PERSONAL'
AND owner_user_id = #{userId}

SELECT FROM meal_item
source_type = 'PERSONAL' AND owner_user_id = #{userId}
source_type = 'PUBLIC' AND owner_user_id IS NULL
AND (#{mealTimeJson} = '[]' OR JSON_OVERLAPS(meal_time, #{mealTimeJson})) AND (#{moodJson} = '[]' OR JSON_OVERLAPS(mood, #{moodJson})) AND (#{sceneJson} = '[]' OR JSON_OVERLAPS(scene, #{sceneJson})) AND (#{healthGoalJson} = '[]' OR JSON_OVERLAPS(health_goal, #{healthGoalJson})) AND (#{cuisineJson} = '[]' OR JSON_OVERLAPS(cuisine, #{cuisineJson})) AND (#{tasteJson} = '[]' OR JSON_OVERLAPS(taste, #{tasteJson})) AND (#{convenienceJson} = '[]' OR JSON_OVERLAPS(convenience, #{convenienceJson})) AND (#{maxEnergyKcal} IS NULL OR (energy_kcal IS NOT NULL AND energy_kcal <= #{maxEnergyKcal})) AND (#{minProteinG} IS NULL OR (protein_g IS NOT NULL AND protein_g >= #{minProteinG})) AND (#{maxFatG} IS NULL OR (fat_g IS NOT NULL AND fat_g <= #{maxFatG})) AND (#{maxCarbohydrateG} IS NULL OR (carbohydrate_g IS NOT NULL AND carbohydrate_g <= #{maxCarbohydrateG})) AND (#{maxSodiumMg} IS NULL OR (sodium_mg IS NOT NULL AND sodium_mg <= #{maxSodiumMg})) AND ( #{excludedAllergensJson} = '[]' OR (allergens IS NOT NULL AND NOT JSON_OVERLAPS(allergens, #{excludedAllergensJson})) )
ORDER BY updated_at DESC LIMIT #{limit}

SELECT FROM meal_item
source_type = 'PERSONAL' AND owner_user_id = #{userId}
source_type = 'PUBLIC' AND owner_user_id IS NULL
AND (#{maxEnergyKcal} IS NULL OR (energy_kcal IS NOT NULL AND energy_kcal <= #{maxEnergyKcal})) AND (#{minProteinG} IS NULL OR (protein_g IS NOT NULL AND protein_g >= #{minProteinG})) AND (#{maxFatG} IS NULL OR (fat_g IS NOT NULL AND fat_g <= #{maxFatG})) AND (#{maxCarbohydrateG} IS NULL OR (carbohydrate_g IS NOT NULL AND carbohydrate_g <= #{maxCarbohydrateG})) AND (#{maxSodiumMg} IS NULL OR (sodium_mg IS NOT NULL AND sodium_mg <= #{maxSodiumMg})) AND ( #{excludedAllergensJson} = '[]' OR (allergens IS NOT NULL AND NOT JSON_OVERLAPS(allergens, #{excludedAllergensJson})) )
ORDER BY updated_at DESC LIMIT #{limit}

SELECT FROM meal_item
source_type = 'PERSONAL' AND owner_user_id = #{userId}
source_type = 'PUBLIC' AND owner_user_id IS NULL
AND id IN
#{id}
